import heapq

def shortest_path(edges, start, end):
    # 1. Check for negative weights
    for _, _, weight in edges:
        if weight < 0:
            raise ValueError("Edge weights cannot be negative.")

    # 2. Base case: start and end are the same
    if start == end:
        return (0, [start])

    # 3. Build the adjacency list
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        graph[u].append((v, w))
        # Ensure 'end' or nodes with no outgoing edges are in the graph representation
        if v not in graph:
            graph[v] = []

    # If start is not in the graph, no path exists
    if start not in graph:
        return (None, None)

    # 4. Priority queue for Dijkstra's algorithm: stores (distance, current_node, path)
    pq = [(0, start, [start])]

    # 5. Visited set
    visited = set()

    # 6. Algorithm Execution
    while pq:
        current_distance, current_node, path = heapq.heappop(pq)

        if current_node == end:
            return (current_distance, path)

        if current_node in visited:
            continue

        visited.add(current_node)

        for neighbor, weight in graph.get(current_node, []):
            if neighbor not in visited:
                heapq.heappush(pq, (current_distance + weight, neighbor, path + [neighbor]))

    # 7. If the loop finishes without reaching 'end', no path exists
    return (None, None)
